import { Component, OnInit } from '@angular/core';

import { ModalController, NavParams } from '@ionic/angular';
import { ViewImagePage } from '../view-image/view-image.page';
import { UploadService } from 'src/app/services/emis/upload.service';
import { AlertService } from 'src/app/services/alert.service';


@Component({
  selector: 'app-summarypopuppage',
  templateUrl: './summarypopuppage.page.html',
  styleUrls: ['./summarypopuppage.page.scss'],
})
export class SummarypopuppagePage implements OnInit {

  items: any[];
  reportname:string;
  schoolname:string;


  constructor(private uploadService: UploadService, private modalCtrl: ModalController , private alertService: AlertService,
    private navParams: NavParams) { }

  ngOnInit() {
    this.reportname = this.navParams.get('reportname');
    this.schoolname = this.navParams.get('schoolname');
  }

  closeModal() {
    this.modalCtrl.dismiss();
  }

  async openDateModal(item){
    if (item.image) {
      var bucketName = "renewalapplicationemis";
      var filename = item.image;
      let expiry: number = 1800;
      this.uploadService.getUploadedFiles(bucketName, filename, expiry).subscribe(async (result) => {
        console.log(item.date_ts);
        if (result) {
          const modal = await this.modalCtrl.create({
            component: ViewImagePage,
            componentProps: { image: result.url},
            cssClass: 'view-image-modal_capturedimage'
          });
          await modal.present();
        }
        else {
          this.alertService.error('Error while getting image');
        }
      });
    } else {
      this.alertService.warning('No data found');
    }
    }

    async addWatermark(imageUrl: string, watermarkText: any): Promise<string> {
      return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "Anonymous"; // To avoid CORS issues
        img.src = imageUrl;
    
        img.onload = () => {
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");
    
          if (!ctx) {
            reject("Canvas context not available");
            return;
          }
    
          // Set canvas size to match the image
          canvas.width = img.width;
          canvas.height = img.height;
    
          // Draw the original image
          ctx.drawImage(img, 0, 0);
    
          // Set watermark properties
          ctx.font = "bold 40px Arial";
          ctx.fillStyle = "rgba(255, 255, 255, 0.7)"; // Semi-transparent white
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
    
          // Position watermark at the bottom-right corner
          const x = canvas.width - 150;
          const y = canvas.height - 50;
    
          // Draw watermark text
          ctx.fillText(watermarkText, x, y);
    
          // Convert canvas to image URL
          resolve(canvas.toDataURL("image/png"));
        };
    
        img.onerror = (error) => reject(error);
      });
    }
}
