import { Component, OnInit, SecurityContext } from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';
import { ModalController, NavParams } from '@ionic/angular';

@Component({
  selector: 'app-view-pdf',
  templateUrl: './view-pdf.page.html',
  styleUrls: ['./view-pdf.page.scss'],
})
export class ViewPdfPage implements OnInit {
  data: any;
  imageURL: any;
  // imageURL1: any;
  // video: any;
  id: any;
  embedurl: any;
  urlSafe: any;
  url: any;
  pdfLink: any;
  src: string;

  docname :any;
  filename:any;
  gradeId ;
  unitId ;
  periodId;
  pdfName;
  indexId;
  noOfLikes: number = 0;
  noOfDisLikes: number = 0;
  likeClass = ['like-button'];
  likeState: string = '';
  isActive: boolean;
  reaction ;
  sessionTeacherId;
  sessionEmisUserType;
  sessionSchoolId;
  zoom_to;
  docLink:any;
  ItemData: any; 
  BookLikeList: any;

  iconColor: string = '#000';
  zoom: number = 1.0;
  originalSize: boolean = true;
  termId;
  comment : any
  extension: any;
  ext: any;

  constructor(
    private sanitizer: DomSanitizer, 
    private modalCtrl: ModalController, 
    private navParams: NavParams
  ) { 

  }

  ngOnInit() {
    
  }

  ionViewDidEnter() {
    this.extension = this.navParams.get('extension');
    this.imageURL = this.navParams.get('image');
    this.src =this.imageURL;
    this.ext = this.extension.toLowerCase();
  }

  incrementZoom(amount: number) {
    this.zoom += amount;   
  }

  zoom_in() {
    this.zoom_to = this.zoom_to + 0.25;
  }

  zoom_out() {
    if (this.zoom_to > 1) {
       this.zoom_to = this.zoom_to - 0.25;
    }
  }

  getPDFUrl() {
    const url = this.sanitizer.sanitize(SecurityContext.URL, this.imageURL.toString());
    let embedurl = this.sanitizer.bypassSecurityTrustResourceUrl(url);
    return embedurl;
  }

  closeModal(){
    this.modalCtrl.dismiss();
  }
}