import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { ModalController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { DiagnosisService } from 'src/app/services/diagnosis.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-mht-view-modal',
  templateUrl: './mht-view-modal.page.html',
  styleUrls: ['./mht-view-modal.page.scss'],
})
export class MhtViewModalPage implements OnInit {
  UserName: any;
  filterBy: any;
  diagnoses: any[] = [];
  filterDiagnosis: any;
  jsonData: any;
  fltDiagnosis: any[] = [];
  disabledItems: any[]=[];

  constructor(private usersessionService: UserSessionService,private alert: AlertService, private router: Router,
    private modalCtrl: ModalController, private alertService: AlertService, private diagnosisService: DiagnosisService
  ) { 
    
    this.UserName = this.usersessionService.emis_username();
    this.diagnoses = this.diagnosisService.getDiagnoses();
  }

  ngOnInit() {
  }

  ionViewWillEnter() {

    var checkViewType = localStorage.getItem('viewType');
    this.jsonData = '';
    if(checkViewType && checkViewType != undefined){
      this.jsonData = JSON.parse(checkViewType);
      this.filterBy = this.jsonData.type;
      this.filterDiagnosis = this.jsonData.diagnosis;
      if(this.filterBy != '2'){
        if(this.filterBy == '1'){
          this.fltDiagnosis=[
            { type: this.filterBy, value: 'All', label: `All`, selected: false },
            ...this.diagnoses
          ];
          if(this.filterDiagnosis.length == 0 ){
            this.filterDiagnosis.push({ type: this.filterBy, value: 'All', label: `All`});
          }
        }
        else{
          this.fltDiagnosis=[
            { type: this.filterBy, value: 'All', label: `All`},
            ...this.diagnoses.filter((item) => item.type === this.filterBy)
          ];
          if(this.filterDiagnosis.length == 0 ){
            this.filterDiagnosis.push({ type: this.filterBy, value: 'All', label: `All`});
          }
        }
        this.onSelectionChange2();
      }
      else{
        this.fltDiagnosis = [];
      }
    }
  }

  onGoButton() {
    this.modalCtrl.dismiss();
    if(this.jsonData && this.jsonData != undefined){
      this.router.navigate(['/tabs/school-list-mht']);
    }
    else{
      this.router.navigate(['/tabs/home']);
    }
  }

  closeModal() {
    let obj = {};
    if(this.filterBy){
      if(this.filterBy != '2'){
          if(this.filterDiagnosis[0].value === 'All'){
            obj = {
              type : this.filterBy,
              diagnosis: []
            }
          }
          else{
            obj = {
              type : this.filterBy,
              diagnosis: this.filterDiagnosis
            }
          }

        this.modalCtrl.dismiss(obj); // Dismiss the modal
      }
      else if(this.filterBy == '2'){
        obj = {
          type : this.filterBy,
          diagnosis: []
        }

        this.modalCtrl.dismiss(obj); // Dismiss the modal
      }
      else{
        this.alertService.warning("Please select the diagnosis");
      }
    }
    else{
      this.alertService.warning("Please select the field");
    }
  }

  selectFilterBy(){
    this.filterDiagnosis = [];
    this.fltDiagnosis = [];
    if(this.filterBy != 1){
      this.fltDiagnosis=[
        { type: this.filterBy, value: 'All', label: `All` },
        ...this.diagnoses.filter((item) => item.type === this.filterBy)
      ]; 
    }
    else{
      this.fltDiagnosis=[
        { type: this.filterBy, value: 'All', label: `All`},
        ...this.diagnoses
      ];
    }
    this.onSelectionChange2();
  }

  onSelectionChange(event: any, ionicSelectable: any) {
    if (event.isSelected === true && event.item.value === 'All') {
      this.filterDiagnosis = []
      this.filterDiagnosis = [{ type: this.filterBy, value: 'All', label: `All` }]; 
      this.disabledItems = this.fltDiagnosis.filter((item) => item.value !== 'All');
      ionicSelectable.close();
    } else {
      this.disabledItems = [];
    }
  }

  onSelectionChange2() {
    if (this.filterDiagnosis.some(item => item.value === 'All')) {
      this.filterDiagnosis = [{ type: this.filterBy, value: 'All', label: `All` }]; // Reset selection to only "All"
      this.disabledItems = this.fltDiagnosis.filter((item) => item.value !== 'All');
    } else {
      this.disabledItems = [];
    }
  }
}
