import { Component, Input, OnInit } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { ModalController, NavParams } from '@ionic/angular';
import { LoadingService } from 'src/app/services/tnvn/services/loading.service';

@Component({
  selector: 'app-view-pdf',
  templateUrl: './view-pdf.page.html',
  styleUrls: ['./view-pdf.page.scss'],
})
export class ViewPdfPage implements OnInit {
  @Input() filename: string;
  @Input() Heading: string;

  PDFFileName: any
  show: boolean = false;

  constructor(private domsaintizer: DomSanitizer, private loader: LoadingService, private modalController: ModalController,
    private navParams: NavParams) { }

  ngOnInit() {

  }

  ionViewDidEnter() {
    this.filename = ''
    this.filename = this.navParams.get('image');
    this.Heading = this.navParams.get('name');    
    this.loader.show()    
      this.PDFFileName = this.domsaintizer.bypassSecurityTrustResourceUrl("https://d1p3r7kc5uix85.cloudfront.net/" + this.filename);      
    setTimeout(() => {      
    }, 5000);

  }

  dismiss() {
    this.modalController.dismiss({
      'dismissed': true
    });
  }

}