import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormControl, FormControlName, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertController, ModalController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { CWSNService } from 'src/app/services/cwsn.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { LoaderServiceService } from 'src/app/services/tnvn/services/common_Provider/loader-service/loader-service.service';

@Component({
  selector: 'app-cwsn-attend-filter',
  templateUrl: './cwsn-attend-filter.page.html',
  styleUrls: ['./cwsn-attend-filter.page.scss'],
})
export class CwsnAttendFilterPage implements OnInit {
  
  @ViewChild('pdfContent') pdfContent: ElementRef;
  fromDate:any;
  toDate:any;
  userId:any;
  attenHistory:any = [];
  filteredHistory:any = [];
  todayDate: any;
  teacherName: any;

    constructor(private router: Router, private modalCtrl: ModalController,
      private cWSNService: CWSNService, private datePipe: DatePipe,
      private alertService: AlertService, private loaderSerivce: LoaderServiceService,
      private alertCtrl: AlertController,
      private userSessionService: UserSessionService,
    ) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.todayDate = new Date().toISOString().split('T')[0];
    this.userId = this.userSessionService.emis_username();
    this.teacherName = this.userSessionService.teacher_name();
  }

  filterHistory(){
    if(this.fromDate && this.toDate){
      this.cWSNService.CwsnAttendDate(this.userId, this.datePipe.transform(this.fromDate, 'yyyy-MM-dd'),
       this.datePipe.transform(this.toDate, 'yyyy-MM-dd')).subscribe(res =>{
        if(res.dataStatus){
          this.filteredHistory = res.result;
        }else{
          this.alertService.error(res.message);
        }
      })
    }else{
      this.alertService.error("Please select date");
    }
  }

  closeModal() {
    this.fromDate = "";
    this.toDate = "";
    this.modalCtrl.dismiss();
  }

  getPDF() {
    debugger
    if (!Array.isArray(this.filteredHistory)) {
      console.error('filteredHistory is not a valid array');
      return;
    }

    const data: any = document.getElementById('pdfContent');
    if (!data) return;
    this.loaderSerivce.presentLoadingTillDismiss();
    data.style.display = 'block';
    if (data) {
      html2canvas(data, {
        scale: 1, 
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff'
      }).then(canvas => {
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const imgProps = pdf.getImageProperties(imgData);
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
        const formattedDate = `${this.datePipe.transform(this.fromDate, 'yyyy-MM-dd')} to ${this.datePipe.transform(this.toDate, 'yyyy-MM-dd')}`

        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
        pdf.save(formattedDate+'_Attendance.pdf');
      }).finally(() => {
        data.style.display = 'none';
        this.loaderSerivce.isLoading = false;
        this.loaderSerivce.dismissLoader();
      });
    }
  }

}
